import {mountTicketCreation} from './tickets-ui.js';
import {reconcile} from './reconcile.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let snapshot=null,search='',type='',offset=0,busy=false,controller;
function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('traceworks-jira',1);r.onupgradeneeded=()=>r.result.createObjectStore('imports');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Local ticket storage is unavailable.'));});}
async function storage(value){const d=await db();try{return await new Promise((resolve,reject)=>{const t=d.transaction('imports',value?'readwrite':'readonly'),s=t.objectStore('imports');let result;const r=value?s.put(value,'latest'):s.get('latest');r.onsuccess=()=>result=r.result;t.oncomplete=()=>resolve(result);t.onerror=()=>reject(Error('Unable to save tickets. Free local browser storage and retry.'));t.onabort=()=>reject(Error('Import could not be saved. Previous import is unchanged.'));});}finally{d.close();}}
function ticketTable(){if(!snapshot)return '<div class="empty">Connect Jira to import tickets. Your sample workspace stays available in the other views.</div>';const rows=snapshot.issues.filter(i=>(!type||i.type===type)&&(i.key+' '+i.summary).toLowerCase().includes(search.toLowerCase()));offset=Math.min(offset,Math.max(0,Math.floor((rows.length-1)/50)*50));return `<div class="table-wrap"><table><thead><tr><th>Ticket</th><th>Type</th><th>Status</th><th>Parent</th><th>Links</th></tr></thead><tbody>${rows.slice(offset,offset+50).map(i=>`<tr><td><a class="link" href="${esc(snapshot.site+'/browse/'+encodeURIComponent(i.key))}" target="_blank" rel="noopener noreferrer">${esc(i.key)}</a><div>${esc(i.summary)}</div></td><td>${esc(i.type)}</td><td>${esc(i.status)}</td><td>${esc(typeof i.parent==='string'?i.parent:i.parent?'Unrecognized parent value':'—')}</td><td>${i.links.map(l=>`${esc(l.type)} (${esc(l.direction)}): ${esc(l.key)}`).join('<br>')||'—'}</td></tr>`).join('')||'<tr><td colspan="5">No matching tickets.</td></tr>'}</tbody></table></div><div class="panel-head"><span>${rows.length?offset+1:0}–${Math.min(offset+50,rows.length)} of ${rows.length}</span><div class="actions"><button data-jira-page="-1" ${offset===0?'disabled':''}>Previous</button><button data-jira-page="1" ${offset+50>=rows.length?'disabled':''}>Next</button></div></div>`;}
function coverage(){if(!snapshot)return '';const counts=new Map();for(const i of snapshot.issues)counts.set(i.type,(counts.get(i.type)||0)+1);return `<div class="intro">Imported Jira inventory · ${snapshot.issues.length} tickets · ${esc(snapshot.scope)} · ${esc(new Date(snapshot.at).toLocaleString())}<br>${[...counts].map(([t,n])=>`${esc(t)}: ${n}`).join(' · ')}<p>Parent and issue links are preserved as Jira reports them. Government RPM equivalence still needs explicit field/link mapping; imported tickets are not mixed with sample coverage.</p></div>`;}
export async function showJira(){const root=document.querySelector('#content');root.innerHTML=`<div class="heading"><div><h1>Jira integration</h1><p>Import all visible tickets in a project or across your Jira site.</p></div></div><section class="panel"><div class="panel-head"><h2>Connect and import</h2><span class="pill">Manual import is read-only</span></div><form id="jira-form" style="padding:24px"><div class="split"><label class="field">Jira deployment<select name="kind"><option value="cloud">Jira Cloud</option><option value="dc">Jira Data Center</option></select></label><label class="field">Jira base URL<input name="url" type="url" value="" placeholder="https://your-team.atlassian.net" required></label><label class="field">Atlassian email (Cloud)<input name="email" type="email" autocomplete="username"></label><label class="field">API token (Cloud) or personal access token (Data Center)<input name="token" type="password" autocomplete="off" required></label><label class="field">Import scope<select name="scope"><option value="project">One project</option><option value="all">All accessible projects</option></select></label><label class="field">Project key<input name="project" value="" placeholder="PROJECT"></label></div><details><summary>Advanced connection options</summary><label class="field">Cloud ID (required for a scoped Cloud API token)<input name="cloudId" placeholder="Leave blank for an unscoped token"></label><label class="field">Legacy Parent Link field identifier (optional)<input name="parentField" placeholder="customfield_10018"></label></details><p class="muted">Tickets are saved on this device. Manual import credentials are not saved. Daily refresh uses the encrypted retention option. Comments, attachments, and issue history are not downloaded.</p><p><a href="https://id.atlassian.com/manage-profile/security/api-tokens" target="_blank" rel="noopener noreferrer">Manage Atlassian API tokens ↗</a></p><div class="actions"><button class="primary" id="jira-submit">Import tickets</button><button type="button" id="jira-cancel" hidden>Cancel import</button></div><p id="jira-progress" role="status" aria-live="polite"></p></form></section><section class="panel"><div id="jira-summary"></div><div class="panel-head"><h2>Imported tickets</h2><div class="actions"><input id="jira-search" class="filter" aria-label="Search Jira tickets" placeholder="Search key or summary"><select id="jira-type" aria-label="Filter Jira issue type"><option value="">All issue types</option></select></div></div><div id="jira-table">Loading saved import…</div></section>`;
 mountTicketCreation(root); mountSchedule(root); try{snapshot=await storage()||null;}catch(e){root.querySelector('#jira-progress').textContent=e.message;}if(!root.querySelector('#jira-table'))return;refresh();
 root.querySelector('#jira-search').addEventListener('input',e=>{search=e.target.value;offset=0;refreshTable();});root.querySelector('#jira-type').addEventListener('change',e=>{type=e.target.value;offset=0;refreshTable();});root.querySelector('#jira-table').addEventListener('click',e=>{const b=e.target.closest('[data-jira-page]');if(b){offset+=Number(b.dataset.jiraPage)*50;refreshTable();}});
 root.querySelector('#jira-cancel').onclick=()=>controller?.abort();
 root.querySelector('#jira-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const form=e.target,config=Object.fromEntries(new FormData(form)),progress=root.querySelector('#jira-progress');busy=true;controller=new AbortController();form.querySelectorAll('input,select,button[type="submit"],#jira-submit').forEach(x=>x.disabled=true);root.querySelector('#jira-cancel').hidden=false;document.querySelectorAll('nav button').forEach(x=>x.disabled=true);
 try{const issues=new Map(),seen=new Set();let cursor=null,site='',pages=0;do{progress.textContent=`Importing… ${issues.size} tickets received (${pages} pages).`;const r=await fetch('/api/jira/page',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...config,cursor}),signal:controller.signal});const data=await r.json();if(!r.ok)throw Error(data.error||'Import failed.');site=data.site;for(const i of data.issues)issues.set(i.id,i);cursor=data.cursor;pages++;if(cursor!==null){if(seen.has(cursor))throw Error('Jira repeated a page token. Import stopped without replacing saved tickets.');seen.add(cursor);}}while(cursor!==null);if(controller.signal.aborted)throw new DOMException('Cancelled','AbortError');const next={site,scope:config.scope==='all'?'All accessible projects':config.project,at:new Date().toISOString(),issues:[...issues.values()]};next.reconciliation=reconcile(next.issues,snapshot?.site===next.site&&snapshot?.scope===next.scope?snapshot.issues:[]);await storage(next);snapshot=next;search='';type='';offset=0;refresh();progress.textContent=`Imported ${issues.size} tickets across ${pages} pages. Saved locally. Re-import replaces this snapshot without duplicates.`;}catch(err){progress.textContent=err.name==='AbortError'?'Import cancelled. Previous import is unchanged.':err.message;progress.classList.add('error');}finally{config.token='';form.elements.token.value='';form.querySelectorAll('input,select,#jira-submit').forEach(x=>x.disabled=false);root.querySelector('#jira-cancel').hidden=true;document.querySelectorAll('nav button').forEach(x=>x.disabled=false);busy=false;controller=null;}};
}
function refreshTable(){document.querySelector('#jira-table').innerHTML=ticketTable();}
function renderAutomation(){const panel=document.querySelector('#jira-reconciliation');const a=snapshot?.automation;if(!panel||!a)return;panel.insertAdjacentHTML('beforeend',`<div class="panel-head"><h2>Automatic Jira actions</h2><span>${a.actions.length} completed · ${a.review.length} need review</span></div>${a.actions.map(x=>`<div class="list-row"><strong>${esc(x.key)}</strong><span>${esc(x.reason)}</span></div>`).join('')}${a.review.map(x=>`<div class="list-row"><strong>${esc(x.key)}</strong><span class="error">${esc(x.reason)}</span></div>`).join('')}`);}
function renderReconciliation(){let panel=document.querySelector('#jira-reconciliation');if(!panel){panel=document.createElement('section');panel.id='jira-reconciliation';panel.className='panel';document.querySelector('#content').append(panel);}const r=snapshot?.reconciliation;panel.innerHTML=`<div class="panel-head"><h2>Automatic reconciliation</h2><span class="pill">Read-only checks</span></div>${r?`<div class="intro">${r.mappings.length} Epic → Initiative links confirmed · ${r.added} new tickets · ${r.updated} updated tickets · ${r.noLongerVisible.length} no longer visible in this scope.<br>Government RPM coverage and ticket creation require configured equivalence rules.</div>${r.findings.map(f=>`<div class="list-row"><strong>${esc(f.key)}</strong><span>${esc(f.reason)}</span></div>`).join('')||'<div class="empty">No issues found by the configured hierarchy checks.</div>'}`:'<div class="empty">Checks run automatically after each completed import.</div>'}`;}
async function scheduleApi(action,input={}){const r=await fetch('/api/jira/schedule/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});const d=await r.json();if(!r.ok)throw Error(d.error||'Schedule request failed.');return d;}
function addRuleSettings(section){const rules=document.createElement('details');rules.innerHTML=`<summary>Automatic Jira changes — configure rules</summary><label style="display:flex;gap:10px;margin:16px 0"><input id="auto-writes" type="checkbox" style="width:auto">Create missing Initiatives and assign unparented Epics using these rules</label><div class="split">${[['requirementType','Requirement issue type','Requirement'],['initiativeType','Initiative issue type','Initiative'],['epicType','Epic issue type','Epic'],['project','Project for new Initiatives',''],['equivalenceLink','Equivalence link type name (Initiative → Requirement)',''],['epicLink','Parent-candidate link type name (Epic → Initiative)','']].map(([key,label,value])=>`<label class="field">${label}<input data-rule="${key}" value="${value}"></label>`).join('')}</div><p>Use exact Jira issue and link type names. Arrows specify the outward link direction. A single explicit candidate is required for Epic assignment. Ambiguous matches and missing required Jira fields are left for review. No title-based matching or government Requirement creation is performed.</p>`;section.querySelector('#retain-jira').closest('label').before(rules);}
function mountSchedule(root){let section=document.createElement('section');section.className='panel';section.innerHTML=`<div class="panel-head"><h2>Daily refresh</h2><span class="pill">Every 24 hours</span></div><div style="padding:24px"><p>Refresh Jira and check hierarchy links automatically. Runs while this computer and server are on; a missed run is picked up when the server restarts.</p><p>Daily refresh stores a copy of imported tickets on disk and encrypts your token for your Windows account. If this folder is cloud-synced, ticket data and the encrypted token may be synced too.</p><label style="display:flex;gap:10px;margin:18px 0"><input id="retain-jira" type="checkbox" style="width:auto">Save my Jira credential encrypted for daily refresh</label><div class="actions"><button id="enable-daily" type="button">Enable daily refresh</button><button id="pause-daily" type="button">Pause</button><button id="run-daily" type="button">Refresh now</button><button id="check-daily" type="button">Check status / load latest</button></div><p id="daily-status" role="status" aria-live="polite">Loading schedule status…</p></div>`;root.querySelector('.heading').after(section);
 addRuleSettings(section); const message=section.querySelector('#daily-status');
 const update=async(load=false)=>{try{const s=await scheduleApi('status');if(!section.isConnected)return;message.textContent=`${s.enabled?'Enabled':'Not enabled'}${s.running?' · Refresh in progress':''}${s.nextRun?' · Next: '+new Date(s.nextRun).toLocaleString():''}${s.lastSuccess?' · Last success: '+new Date(s.lastSuccess).toLocaleString():''}${s.error?' · Last error: '+s.error:''}`;section.querySelector('#run-daily').disabled=!s.enabled||s.running;section.querySelector('#pause-daily').disabled=!s.enabled||s.running;if(load||s.lastSuccess&&s.lastSuccess!==snapshot?.at){const next=await scheduleApi('snapshot');if(next&&section.isConnected){await storage(next);snapshot=next;refresh();}}}catch(e){message.textContent=e.message;}};
 section.querySelector('#enable-daily').onclick=async()=>{const form=root.querySelector('#jira-form');if(!form.reportValidity())return;if(!section.querySelector('#retain-jira').checked){message.textContent='Check the encrypted credential option to enable daily refresh.';return;}const config=Object.fromEntries(new FormData(form));config.rules={enabled:section.querySelector('#auto-writes').checked};section.querySelectorAll('[data-rule]').forEach(x=>config.rules[x.dataset.rule]=x.value.trim());try{await scheduleApi('configure',{...config,enabled:true,retainCredential:true});form.elements.token.value='';await scheduleApi('run');await update();}catch(e){message.textContent=e.message;}finally{config.token='';}};
 section.querySelector('#pause-daily').onclick=async()=>{try{await scheduleApi('configure',{enabled:false});await update();}catch(e){message.textContent=e.message;}};
 section.querySelector('#run-daily').onclick=async()=>{try{await scheduleApi('run');await update();}catch(e){message.textContent=e.message;}};
 section.querySelector('#check-daily').onclick=()=>update(true);update();
 const timer=setInterval(()=>{if(!section.isConnected){clearInterval(timer);return;}if(!busy)update();},15000);
}
function refresh(){renderReconciliation();renderAutomation();document.querySelector('#jira-summary').innerHTML=coverage();document.querySelector('#jira-search').value=search;document.querySelector('#jira-type').innerHTML='<option value="">All issue types</option>'+[...new Set(snapshot?.issues.map(i=>i.type)||[])].sort().map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');refreshTable();}






